// Reads of the public campaign data. These are the same requests the production site makes
// (external contracts, see CLAUDE.md): `GET /rest/v1/campaigns?slug=eq.X&status=eq.active`
// and `campaign_progress(p_slugs)`. Everything is read with the publishable key.

import { resolveSupabaseKey, resolveSupabaseUrl } from '../common/runtime-config';

export interface OtherLink {
  label: string;
  url: string;
}

/** A row of `campaigns` as the public pages read it (`select=*`). */
export interface Campaign {
  id: string;
  slug: string;
  name: string;
  organizer_name: string;
  description: string;
  goal_cents: number;
  image_url: string | null;
  target_date: string | null;
  twitch_url: string | null;
  youtube_url: string | null;
  tiktok_url: string | null;
  instagram_url: string | null;
  discord_url: string | null;
  other_links: OtherLink[] | null;
}

/** A row of `campaign_progress()`. Columns are only ever added, never removed (external contract). */
export interface CampaignProgress {
  slug: string;
  name: string;
  image_url: string | null;
  goal_cents: number;
  raised_cents: number;
  target_date: string | null;
}

function authHeaders(): Record<string, string> {
  const key = resolveSupabaseKey();
  return { apikey: key, Authorization: `Bearer ${key}` };
}

/** POST to a Postgres function through the Data API. */
export async function rpc<T>(name: string, args: Record<string, unknown> = {}): Promise<T> {
  const res = await fetch(`${resolveSupabaseUrl()}/rest/v1/rpc/${name}`, {
    method: 'POST',
    headers: { ...authHeaders(), 'Content-Type': 'application/json' },
    body: JSON.stringify(args),
  });
  if (!res.ok) throw new Error(`RPC ${name} failed: ${res.status}`);
  return res.json() as Promise<T>;
}

/** The active campaign with this slug, or null when there is none. */
export async function fetchCampaign(slug: string): Promise<Campaign | null> {
  const res = await fetch(
    `${resolveSupabaseUrl()}/rest/v1/campaigns?slug=eq.${encodeURIComponent(slug)}&status=eq.active&select=*`,
    { headers: authHeaders() },
  );
  if (!res.ok) throw new Error('Request failed');
  const rows = (await res.json()) as Campaign[];
  return rows.length ? rows[0] : null;
}

/** Progress of the given campaigns, or of every active one when `slugs` is null. */
export function fetchProgress(slugs: string[] | null): Promise<CampaignProgress[]> {
  return rpc<CampaignProgress[]>('campaign_progress', { p_slugs: slugs });
}
